(n_bit, line_count) = [int(i) for i in input().split()]
a = int(input(), 2)
b = int(input(), 2)
for i in range(line_count):
	inp = input().split()
	x = int(inp[1])
	if inp[0] == 'get_c':
		print((a + b & 1 << x) >> x, end='')
	elif inp[0] == 'set_a':
		if inp[2] == '1':
			a = a | 1 << x
		else:
			a = a & ~(1 << x)
	elif inp[2] == '1':
		b = b | 1 << x
	else:
		b = b & ~(1 << x)
